'use strict';

// Read model for the items service. Writes are owned by the storage worker;
// the request handler only validates and normalizes payloads for it.
const items = [
  { id: 'a1', name: 'anchor bolt', qty: 12 },
  { id: 'b2', name: 'brass washer', qty: 40 },
  { id: 'c3', name: 'copper lug', qty: 7 },
];

function listItems() {
  return items.slice();
}

module.exports = { listItems };

