'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { handle } = require('./src/handler.js');

test('s1 methods outside the allowlist get 405 method_not_allowed', () => {
  const removed = handle({ method: 'DELETE', path: '/api/items', query: {}, headers: {} });
  assert.strictEqual(removed.status, 405);
  assert.strictEqual(removed.body.error, 'method_not_allowed');

  const patched = handle({ method: 'PATCH', path: '/api/status', query: {}, headers: {} });
  assert.strictEqual(patched.status, 405);
  assert.strictEqual(patched.body.error, 'method_not_allowed');

  const replaced = handle({ method: 'PUT', path: '/api/items', query: {}, headers: {}, body: '{"id":"z9"}' });
  assert.strictEqual(replaced.status, 405);
  assert.strictEqual(replaced.body.error, 'method_not_allowed');

  const postedToStatus = handle({
    method: 'POST',
    path: '/api/status',
    query: {},
    headers: {},
    body: '{"id":"z9","name":"zinc nut","qty":5}',
  });
  assert.strictEqual(postedToStatus.status, 405, 'a route serving GET alone answers POST with 405, not 404');
  assert.strictEqual(postedToStatus.body.error, 'method_not_allowed');

  const listed = handle({ method: 'GET', path: '/api/items', query: {}, headers: {} });
  assert.strictEqual(listed.status, 200);
  assert.ok(Array.isArray(listed.body.items), 'GET /api/items still returns the item list');

  const status = handle({ method: 'GET', path: '/api/status', query: {}, headers: {} });
  assert.strictEqual(status.status, 200);
  assert.strictEqual(status.body.status, 'ok');
});

