'use strict';

const { listItems } = require('./store.js');

// Request handler for the items service.
//
// A request is a plain object:
//   { method, path, query, headers, body }
// query values arrive as the raw strings from the query string, headers as the
// raw bag the proxy passes through, and body as the raw request body string.
//
// A response is { status, headers, body }.

const ALLOWED_METHODS = ['GET', 'POST'];
const ITEM_FIELDS = ['id', 'name', 'qty'];

function json(status, body) {
  return { status: status, headers: {}, body: body };
}

function headerValue(headers, name) {
  const wanted = String(name).toLowerCase();
  for (const key of Object.keys(headers || {})) {
    if (key.toLowerCase() === wanted) return headers[key];
  }
  return undefined;
}

function normalizePath(rawPath) {
  const text = String(rawPath === undefined || rawPath === null ? '' : rawPath).toLowerCase();
  if (text.length > 1 && text.endsWith('/')) return text.slice(0, -1);
  return text;
}

function readCount(raw, fallback) {
  if (raw === undefined || raw === null || String(raw).trim() === '') {
    return { value: fallback };
  }
  const text = String(raw).trim();
  if (!/^[0-9]+$/.test(text)) return { error: true };
  return { value: Number(text) };
}

function readFields(raw) {
  if (raw === undefined || raw === null) return { value: null };
  const names = String(raw).split(',').map((part) => part.trim());
  for (const name of names) {
    if (name === '' || !ITEM_FIELDS.includes(name)) return { error: true };
  }
  return { value: names };
}

function readSort(raw) {
  if (raw === undefined || raw === null) return { value: null };
  const text = String(raw).trim();
  const descending = text.startsWith('-');
  const key = descending ? text.slice(1) : text;
  if (!ITEM_FIELDS.includes(key)) return { error: true };
  return { value: { key: key, descending: descending } };
}

function compareOn(sort) {
  return function (left, right) {
    const a = left[sort.key];
    const b = right[sort.key];
    let cmp = 0;
    if (a < b) cmp = -1;
    else if (a > b) cmp = 1;
    return sort.descending ? -cmp : cmp;
  };
}

function project(item, fields) {
  if (!fields) return item;
  const out = {};
  for (const name of ITEM_FIELDS) {
    if (fields.includes(name)) out[name] = item[name];
  }
  return out;
}

function getItems(req) {
  const query = req.query || {};
  const all = listItems();
  const offset = readCount(query.offset, 0);
  const limit = readCount(query.limit, all.length);
  const fields = readFields(query.fields);
  const sort = readSort(query.sort);
  if (offset.error || limit.error || fields.error || sort.error) {
    return json(400, { error: 'bad_query' });
  }
  const ordered = sort.value ? all.slice().sort(compareOn(sort.value)) : all;
  const page = ordered.slice(offset.value, offset.value + limit.value);
  const res = json(200, {
    items: page.map((item) => project(item, fields.value)),
    offset: offset.value,
    limit: limit.value,
    total: all.length,
  });
  res.headers['x-item-range'] = page.length
    ? offset.value + '-' + (offset.value + page.length - 1) + '/' + all.length
    : '*/' + all.length;
  return res;
}

function firstBadField(payload) {
  if (typeof payload.id !== 'string' || payload.id.trim() === '') return 'id';
  if (typeof payload.name !== 'string' || payload.name.trim() === '') return 'name';
  if (typeof payload.qty !== 'number' || !Number.isInteger(payload.qty) || payload.qty < 0) return 'qty';
  return null;
}

function postItem(req) {
  if (req.body === undefined || req.body === null || String(req.body).trim() === '') {
    return json(400, { error: 'missing_body' });
  }
  let payload;
  try {
    payload = JSON.parse(req.body);
  } catch (err) {
    return json(400, { error: 'invalid_json' });
  }
  if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
    return json(400, { error: 'invalid_json' });
  }
  const bad = firstBadField(payload);
  if (bad) return json(400, { error: 'invalid_item', field: bad });
  if (listItems().some((item) => item.id === payload.id)) {
    return json(409, { error: 'duplicate_id' });
  }
  return json(201, {
    item: { id: payload.id, name: payload.name, qty: payload.qty },
  });
}

function getStatus() {
  return json(200, { status: 'ok' });
}

const routes = {
  '/api/items': { GET: getItems, POST: postItem },
  '/api/status': { GET: getStatus },
};

function allowedOn(route) {
  return ALLOWED_METHODS.filter((method) => route[method]).join(', ');
}

function withRequestId(req, res) {
  const requestId = headerValue(req.headers, 'x-request-id');
  if (requestId !== undefined) res.headers['x-request-id'] = requestId;
  return res;
}

function handle(req) {
  const route = routes[normalizePath(req.path)];
  if (!route) return withRequestId(req, json(404, { error: 'not_found' }));
  if (!ALLOWED_METHODS.includes(req.method) || !route[req.method]) {
    const res = json(405, { error: 'method_not_allowed' });
    res.headers.allow = allowedOn(route);
    return withRequestId(req, res);
  }
  return withRequestId(req, route[req.method](req));
}

module.exports = { handle };
